    CASE WHEN lower(trim(`quality_inspection_required`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`quality_inspection_required`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `quality_inspection_required`,
    NULLIF(trim(`storage_location_code`), '') AS `storage_location_code`,
    NULLIF(trim(`sustainability_certification`), '') AS `sustainability_certification`,
    TRY_CAST(NULLIF(trim(`target_quantity`), '') AS DECIMAL(18,3)) AS `target_quantity`,
    NULLIF(trim(`target_quantity_uom`), '') AS `target_quantity_uom`,
    NULLIF(trim(`tax_code`), '') AS `tax_code`,
    TRY_CAST(NULLIF(trim(`unit_price`), '') AS DECIMAL(18,4)) AS `unit_price`,
    COALESCE(try_to_date(trim(`validity_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`validity_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`validity_end_date`) AS DATE)) AS `validity_end_date`,
    COALESCE(try_to_date(trim(`validity_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`validity_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`validity_start_date`) AS DATE)) AS `validity_start_date`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_contract_line
)
SELECT *
FROM typed
QUALIFY `contract_line_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `contract_line_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- procurement.purchase_requisition ----------------------------------------------------------------
