)
COMMENT 'Silver: procurement.purchase_requisition typed and cleaned, one row per purchase_requisition_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`purchase_requisition_id`), '') AS BIGINT) AS `purchase_requisition_id`,
    TRY_CAST(NULLIF(trim(`demand_plan_id`), '') AS BIGINT) AS `demand_plan_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`planned_order_id`), '') AS BIGINT) AS `planned_order_id`,
    TRY_CAST(NULLIF(trim(`preferred_supplier_id`), '') AS BIGINT) AS `preferred_supplier_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`requesting_cost_center_id`), '') AS BIGINT) AS `requesting_cost_center_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`spend_category_id`), '') AS BIGINT) AS `spend_category_id`,
    TRY_CAST(NULLIF(trim(`supplier_contract_id`), '') AS BIGINT) AS `supplier_contract_id`,
    TRY_CAST(NULLIF(trim(`supply_network_node_id`), '') AS BIGINT) AS `supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    TRY_CAST(NULLIF(trim(`approval_level`), '') AS INT) AS `approval_level`,
    TRY_CAST(NULLIF(trim(`approval_workflow_reference`), '') AS BIGINT) AS `approval_workflow_reference`,
    COALESCE(try_to_date(trim(`approved_date`), 'yyyy-MM-dd'), try_to_date(trim(`approved_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approved_date`) AS DATE)) AS `approved_date`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`estimated_total_value`), '') AS DECIMAL(18,2)) AS `estimated_total_value`,
    TRY_CAST(NULLIF(trim(`estimated_unit_price`), '') AS DECIMAL(18,4)) AS `estimated_unit_price`,
    NULLIF(trim(`internal_order_number`), '') AS `internal_order_number`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    NULLIF(trim(`material_description`), '') AS `material_description`,
    NULLIF(trim(`material_group_code`), '') AS `material_group_code`,
    NULLIF(trim(`material_number`), '') AS `material_number`,
    NULLIF(trim(`notes`), '') AS `notes`,
    CASE lower(trim(`priority`))
      WHEN 'low' THEN 'low'
      WHEN 'normal' THEN 'normal'
      WHEN 'high' THEN 'high'
      WHEN 'urgent' THEN 'urgent'
      ELSE NULLIF(trim(`priority`), '')
    END AS `priority`,
    NULLIF(trim(`purchase_requisition_status`), '') AS `purchase_requisition_status`,
    NULLIF(trim(`purchasing_group_code`), '') AS `purchasing_group_code`,
    NULLIF(trim(`purchasing_organization_code`), '') AS `purchasing_organization_code`,
    TRY_CAST(NULLIF(trim(`quantity_requested`), '') AS DECIMAL(18,3)) AS `quantity_requested`,
    NULLIF(trim(`rejection_reason`), '') AS `rejection_reason`,
    COALESCE(try_to_date(trim(`requested_date`), 'yyyy-MM-dd'), try_to_date(trim(`requested_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`requested_date`) AS DATE)) AS `requested_date`,
    NULLIF(trim(`requester_email`), '') AS `requester_email`,
    NULLIF(trim(`requester_name`), '') AS `requester_name`,
    COALESCE(try_to_date(trim(`required_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`required_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`required_delivery_date`) AS DATE)) AS `required_delivery_date`,
    NULLIF(trim(`requisition_number`), '') AS `requisition_number`,
    CASE lower(trim(`requisition_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'subcontracting' THEN 'subcontracting'
      WHEN 'consignment' THEN 'consignment'
      WHEN 'stock_transfer' THEN 'stock_transfer'
      WHEN 'service' THEN 'service'
      WHEN 'third_party' THEN 'third_party'
      ELSE NULLIF(trim(`requisition_type`), '')
    END AS `requisition_type`,
    CASE WHEN lower(trim(`sds_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`sds_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sds_required_flag`,
    CASE lower(trim(`source_of_supply`))
      WHEN 'preferred_supplier' THEN 'preferred_supplier'
      WHEN 'contract' THEN 'contract'
      WHEN 'stock_transfer' THEN 'stock_transfer'
      WHEN 'external' THEN 'external'
      WHEN 'internal' THEN 'internal'
      ELSE NULLIF(trim(`source_of_supply`), '')
    END AS `source_of_supply`,
    CASE WHEN lower(trim(`sustainability_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`sustainability_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sustainability_flag`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    NULLIF(trim(`wbs_element`), '') AS `wbs_element`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_purchase_requisition
)
SELECT *
FROM typed
QUALIFY `purchase_requisition_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `purchase_requisition_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- procurement.purchase_order ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.procurement_purchase_order (
  CONSTRAINT `purchase_order_id_not_null` EXPECT (`purchase_order_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: procurement.purchase_order typed and cleaned, one row per purchase_order_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`purchase_order_id`), '') AS BIGINT) AS `purchase_order_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`purchase_requisition_id`), '') AS BIGINT) AS `purchase_requisition_id`,
    TRY_CAST(NULLIF(trim(`sales_order_id`), '') AS BIGINT) AS `sales_order_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`spend_category_id`), '') AS BIGINT) AS `spend_category_id`,
    TRY_CAST(NULLIF(trim(`supplier_contract_id`), '') AS BIGINT) AS `supplier_contract_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`supplier_site_id`), '') AS BIGINT) AS `supplier_site_id`,
    TRY_CAST(NULLIF(trim(`supply_network_node_id`), '') AS BIGINT) AS `supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    COALESCE(try_to_timestamp(trim(`approval_date`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approval_date`) AS TIMESTAMP)) AS `approval_date`,
    NULLIF(trim(`approved_by`), '') AS `approved_by`,
    COALESCE(try_to_date(trim(`cancellation_date`), 'yyyy-MM-dd'), try_to_date(trim(`cancellation_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`cancellation_date`) AS DATE)) AS `cancellation_date`,
    NULLIF(trim(`cancellation_reason`), '') AS `cancellation_reason`,
    COALESCE(try_to_date(trim(`closed_date`), 'yyyy-MM-dd'), try_to_date(trim(`closed_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`closed_date`) AS DATE)) AS `closed_date`,
    COALESCE(try_to_date(trim(`confirmed_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`confirmed_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`confirmed_delivery_date`) AS DATE)) AS `confirmed_delivery_date`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    CASE lower(trim(`edi_status`))
      WHEN 'not_sent' THEN 'not_sent'
      WHEN 'sent' THEN 'sent'
      WHEN 'acknowledged' THEN 'acknowledged'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'error' THEN 'error'
      ELSE NULLIF(trim(`edi_status`), '')
    END AS `edi_status`,
    COALESCE(try_to_timestamp(trim(`edi_transmission_date`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`edi_transmission_date`) AS TIMESTAMP)) AS `edi_transmission_date`,
    TRY_CAST(NULLIF(trim(`freight_amount`), '') AS DECIMAL(18,2)) AS `freight_amount`,
    CASE WHEN lower(trim(`goods_receipt_required`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`goods_receipt_required`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `goods_receipt_required`,
    NULLIF(trim(`incoterms`), '') AS `incoterms`,
    NULLIF(trim(`incoterms_location`), '') AS `incoterms_location`,
    CASE WHEN lower(trim(`invoice_receipt_required`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`invoice_receipt_required`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `invoice_receipt_required`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    TRY_CAST(NULLIF(trim(`net_order_value`), '') AS DECIMAL(18,2)) AS `net_order_value`,
    COALESCE(try_to_date(trim(`order_date`), 'yyyy-MM-dd'), try_to_date(trim(`order_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`order_date`) AS DATE)) AS `order_date`,
    NULLIF(trim(`payment_terms`), '') AS `payment_terms`,
    NULLIF(trim(`po_number`), '') AS `po_number`,
    NULLIF(trim(`po_status`), '') AS `po_status`,
    CASE lower(trim(`po_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'blanket' THEN 'blanket'
      WHEN 'contract' THEN 'contract'
      WHEN 'subcontracting' THEN 'subcontracting'
      WHEN 'consignment' THEN 'consignment'
      WHEN 'framework' THEN 'framework'
      ELSE NULLIF(trim(`po_type`), '')
    END AS `po_type`,
    CASE lower(trim(`priority`))
      WHEN 'urgent' THEN 'urgent'
      WHEN 'high' THEN 'high'
      WHEN 'normal' THEN 'normal'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`priority`), '')
    END AS `priority`,
    NULLIF(trim(`purchasing_group`), '') AS `purchasing_group`,
    NULLIF(trim(`purchasing_organization`), '') AS `purchasing_organization`,
    COALESCE(try_to_date(trim(`requested_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`requested_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`requested_delivery_date`) AS DATE)) AS `requested_delivery_date`,
    COALESCE(try_to_timestamp(trim(`supplier_confirmation_date`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`supplier_confirmation_date`) AS TIMESTAMP)) AS `supplier_confirmation_date`,
    CASE lower(trim(`supplier_confirmation_method`))
      WHEN 'edi_855' THEN 'edi_855'
      WHEN 'supplier_portal' THEN 'supplier_portal'
      WHEN 'email' THEN 'email'
      WHEN 'phone' THEN 'phone'
      WHEN 'fax' THEN 'fax'
      WHEN 'not_confirmed' THEN 'not_confirmed'
      ELSE NULLIF(trim(`supplier_confirmation_method`), '')
    END AS `supplier_confirmation_method`,
    CASE lower(trim(`sustainability_certification`))
      WHEN 'fsc' THEN 'FSC'
      WHEN 'rspo' THEN 'RSPO'
      WHEN 'fair_trade' THEN 'fair_trade'
      WHEN 'organic' THEN 'organic'
      WHEN 'none' THEN 'none'
      ELSE NULLIF(trim(`sustainability_certification`), '')
    END AS `sustainability_certification`,
    TRY_CAST(NULLIF(trim(`tax_amount`), '') AS DECIMAL(18,2)) AS `tax_amount`,
    TRY_CAST(NULLIF(trim(`total_order_value`), '') AS DECIMAL(18,2)) AS `total_order_value`,
    CASE lower(trim(`transport_mode`))
      WHEN 'air' THEN 'air'
      WHEN 'ocean' THEN 'ocean'
      WHEN 'rail' THEN 'rail'
      WHEN 'truck' THEN 'truck'
      WHEN 'courier' THEN 'courier'
      WHEN 'multimodal' THEN 'multimodal'
      ELSE NULLIF(trim(`transport_mode`), '')
    END AS `transport_mode`,
    CASE WHEN lower(trim(`vmi_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`vmi_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `vmi_indicator`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_purchase_order
)
SELECT *
FROM typed
QUALIFY `purchase_order_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `purchase_order_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

