    TRY_CAST(NULLIF(trim(`spend_category_id`), '') AS BIGINT) AS `spend_category_id`,
    CASE WHEN lower(trim(`batch_management_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`batch_management_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `batch_management_indicator`,
    COALESCE(try_to_date(trim(`confirmed_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`confirmed_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`confirmed_delivery_date`) AS DATE)) AS `confirmed_delivery_date`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    CASE WHEN lower(trim(`deletion_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`deletion_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `deletion_indicator`,
    COALESCE(try_to_date(trim(`delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`delivery_date`) AS DATE)) AS `delivery_date`,
    CASE WHEN lower(trim(`goods_receipt_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`goods_receipt_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `goods_receipt_indicator`,
    TRY_CAST(NULLIF(trim(`goods_received_quantity`), '') AS DECIMAL(18,3)) AS `goods_received_quantity`,
    NULLIF(trim(`incoterm_code`), '') AS `incoterm_code`,
    NULLIF(trim(`incoterm_location`), '') AS `incoterm_location`,
    CASE WHEN lower(trim(`invoice_receipt_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`invoice_receipt_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `invoice_receipt_indicator`,
    TRY_CAST(NULLIF(trim(`invoiced_quantity`), '') AS DECIMAL(18,3)) AS `invoiced_quantity`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`lead_time_days`), '') AS INT) AS `lead_time_days`,
    TRY_CAST(NULLIF(trim(`line_number`), '') AS INT) AS `line_number`,
    CASE lower(trim(`line_status`))
      WHEN 'open' THEN 'open'
      WHEN 'partially_received' THEN 'partially_received'
      WHEN 'fully_received' THEN 'fully_received'
      WHEN 'closed' THEN 'closed'
      WHEN 'cancelled' THEN 'cancelled'
      WHEN 'blocked' THEN 'blocked'
      ELSE NULLIF(trim(`line_status`), '')
    END AS `line_status`,
    NULLIF(trim(`manufacturer_part_number`), '') AS `manufacturer_part_number`,
    TRY_CAST(NULLIF(trim(`minimum_order_quantity`), '') AS DECIMAL(18,3)) AS `minimum_order_quantity`,
    TRY_CAST(NULLIF(trim(`net_order_value`), '') AS DECIMAL(18,2)) AS `net_order_value`,
    TRY_CAST(NULLIF(trim(`net_price`), '') AS DECIMAL(18,4)) AS `net_price`,
    TRY_CAST(NULLIF(trim(`ordered_quantity`), '') AS DECIMAL(18,3)) AS `ordered_quantity`,
    TRY_CAST(NULLIF(trim(`outstanding_quantity`), '') AS DECIMAL(18,3)) AS `outstanding_quantity`,
    TRY_CAST(NULLIF(trim(`over_delivery_tolerance_percent`), '') AS DECIMAL(5,2)) AS `over_delivery_tolerance_percent`,
    NULLIF(trim(`plant_code`), '') AS `plant_code`,
    TRY_CAST(NULLIF(trim(`price_unit`), '') AS INT) AS `price_unit`,
    NULLIF(trim(`purchasing_group`), '') AS `purchasing_group`,
    NULLIF(trim(`requisitioner_name`), '') AS `requisitioner_name`,
    NULLIF(trim(`short_text`), '') AS `short_text`,
    NULLIF(trim(`storage_location`), '') AS `storage_location`,
    NULLIF(trim(`supplier_material_number`), '') AS `supplier_material_number`,
    NULLIF(trim(`tax_code`), '') AS `tax_code`,
    TRY_CAST(NULLIF(trim(`under_delivery_tolerance_percent`), '') AS DECIMAL(5,2)) AS `under_delivery_tolerance_percent`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_po_line
)
SELECT *
FROM typed
QUALIFY `po_line_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `po_line_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

