    NULLIF(trim(`delivery_note_number`), '') AS `delivery_note_number`,
    COALESCE(try_to_date(trim(`document_date`), 'yyyy-MM-dd'), try_to_date(trim(`document_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`document_date`) AS DATE)) AS `document_date`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    NULLIF(trim(`gr_document_number`), '') AS `gr_document_number`,
    CASE WHEN lower(trim(`gr_reversal_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gr_reversal_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gr_reversal_flag`,
    CASE lower(trim(`gr_status`))
      WHEN 'posted' THEN 'posted'
      WHEN 'reversed' THEN 'reversed'
      WHEN 'cancelled' THEN 'cancelled'
      WHEN 'pending_inspection' THEN 'pending_inspection'
      WHEN 'blocked' THEN 'blocked'
      ELSE NULLIF(trim(`gr_status`), '')
    END AS `gr_status`,
    NULLIF(trim(`inspection_lot_number`), '') AS `inspection_lot_number`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_date(trim(`manufacturing_date`), 'yyyy-MM-dd'), try_to_date(trim(`manufacturing_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`manufacturing_date`) AS DATE)) AS `manufacturing_date`,
    NULLIF(trim(`movement_type`), '') AS `movement_type`,
    CASE WHEN lower(trim(`otif_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`otif_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `otif_compliance_flag`,
    COALESCE(try_to_date(trim(`posting_date`), 'yyyy-MM-dd'), try_to_date(trim(`posting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`posting_date`) AS DATE)) AS `posting_date`,
    CASE WHEN lower(trim(`quality_inspection_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`quality_inspection_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `quality_inspection_required_flag`,
    TRY_CAST(NULLIF(trim(`received_quantity`), '') AS DECIMAL(18,3)) AS `received_quantity`,
    NULLIF(trim(`receiving_plant_code`), '') AS `receiving_plant_code`,
    NULLIF(trim(`remarks`), '') AS `remarks`,
    NULLIF(trim(`reversal_document_number`), '') AS `reversal_document_number`,
    CASE lower(trim(`reversal_reason_code`))
      WHEN 'quality_reject' THEN 'quality_reject'
      WHEN 'quantity_discrepancy' THEN 'quantity_discrepancy'
      WHEN 'damaged' THEN 'damaged'
      WHEN 'wrong_material' THEN 'wrong_material'
      WHEN 'duplicate_posting' THEN 'duplicate_posting'
      WHEN 'administrative_error' THEN 'administrative_error'
      ELSE NULLIF(trim(`reversal_reason_code`), '')
    END AS `reversal_reason_code`,
    NULLIF(trim(`storage_location_code`), '') AS `storage_location_code`,
    CASE lower(trim(`sustainable_sourcing_certification`))
      WHEN 'fsc' THEN 'FSC'
      WHEN 'rspo' THEN 'RSPO'
      WHEN 'none' THEN 'none'
      ELSE NULLIF(trim(`sustainable_sourcing_certification`), '')
    END AS `sustainable_sourcing_certification`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`unit_price`), '') AS DECIMAL(18,4)) AS `unit_price`,
    TRY_CAST(NULLIF(trim(`valuation_amount`), '') AS DECIMAL(18,2)) AS `valuation_amount`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_goods_receipt
)
SELECT *
FROM typed
QUALIFY `goods_receipt_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `goods_receipt_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- procurement.supplier_invoice ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.procurement_supplier_invoice (
  CONSTRAINT `supplier_invoice_id_not_null` EXPECT (`supplier_invoice_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: procurement.supplier_invoice typed and cleaned, one row per supplier_invoice_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`supplier_invoice_id`), '') AS BIGINT) AS `supplier_invoice_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`material_id`), '') AS BIGINT) AS `material_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`purchase_order_id`), '') AS BIGINT) AS `purchase_order_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`supplier_contract_id`), '') AS BIGINT) AS `supplier_contract_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`supplier_site_id`), '') AS BIGINT) AS `supplier_site_id`,
    NULLIF(trim(`approved_by`), '') AS `approved_by`,
    COALESCE(try_to_timestamp(trim(`approved_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approved_timestamp`) AS TIMESTAMP)) AS `approved_timestamp`,
    COALESCE(try_to_date(trim(`baseline_date`), 'yyyy-MM-dd'), try_to_date(trim(`baseline_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`baseline_date`) AS DATE)) AS `baseline_date`,
    NULLIF(trim(`blocking_reason_code`), '') AS `blocking_reason_code`,
    NULLIF(trim(`blocking_reason_description`), '') AS `blocking_reason_description`,
    TRY_CAST(NULLIF(trim(`cash_discount_days`), '') AS INT) AS `cash_discount_days`,
    TRY_CAST(NULLIF(trim(`cash_discount_percentage`), '') AS DECIMAL(5,2)) AS `cash_discount_percentage`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`discount_amount`), '') AS DECIMAL(18,2)) AS `discount_amount`,
    TRY_CAST(NULLIF(trim(`fiscal_period`), '') AS INT) AS `fiscal_period`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    COALESCE(try_to_date(trim(`goods_receipt_date`), 'yyyy-MM-dd'), try_to_date(trim(`goods_receipt_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`goods_receipt_date`) AS DATE)) AS `goods_receipt_date`,
    TRY_CAST(NULLIF(trim(`gross_amount`), '') AS DECIMAL(18,2)) AS `gross_amount`,
    COALESCE(try_to_date(trim(`invoice_date`), 'yyyy-MM-dd'), try_to_date(trim(`invoice_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`invoice_date`) AS DATE)) AS `invoice_date`,
    NULLIF(trim(`invoice_description`), '') AS `invoice_description`,
    NULLIF(trim(`invoice_number`), '') AS `invoice_number`,
    COALESCE(try_to_date(trim(`invoice_receipt_date`), 'yyyy-MM-dd'), try_to_date(trim(`invoice_receipt_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`invoice_receipt_date`) AS DATE)) AS `invoice_receipt_date`,
    NULLIF(trim(`invoice_status`), '') AS `invoice_status`,
    CASE lower(trim(`invoice_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'credit_memo' THEN 'credit_memo'
      WHEN 'debit_memo' THEN 'debit_memo'
      WHEN 'prepayment' THEN 'prepayment'
      WHEN 'final' THEN 'final'
      WHEN 'proforma' THEN 'proforma'
      ELSE NULLIF(trim(`invoice_type`), '')
    END AS `invoice_type`,
    TRY_CAST(NULLIF(trim(`line_item_count`), '') AS INT) AS `line_item_count`,
    NULLIF(trim(`modified_by`), '') AS `modified_by`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    TRY_CAST(NULLIF(trim(`net_amount`), '') AS DECIMAL(18,2)) AS `net_amount`,
    COALESCE(try_to_date(trim(`payment_date`), 'yyyy-MM-dd'), try_to_date(trim(`payment_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`payment_date`) AS DATE)) AS `payment_date`,
    COALESCE(try_to_date(trim(`payment_due_date`), 'yyyy-MM-dd'), try_to_date(trim(`payment_due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`payment_due_date`) AS DATE)) AS `payment_due_date`,
    CASE lower(trim(`payment_method`))
      WHEN 'wire_transfer' THEN 'wire_transfer'
      WHEN 'ach' THEN 'ach'
      WHEN 'check' THEN 'check'
      WHEN 'credit_card' THEN 'credit_card'
      WHEN 'edi' THEN 'edi'
      WHEN 'other' THEN 'other'
      ELSE NULLIF(trim(`payment_method`), '')
    END AS `payment_method`,
    NULLIF(trim(`payment_reference_number`), '') AS `payment_reference_number`,
    NULLIF(trim(`payment_terms_code`), '') AS `payment_terms_code`,
    NULLIF(trim(`plant_code`), '') AS `plant_code`,
    COALESCE(try_to_date(trim(`posting_date`), 'yyyy-MM-dd'), try_to_date(trim(`posting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`posting_date`) AS DATE)) AS `posting_date`,
    TRY_CAST(NULLIF(trim(`tax_amount`), '') AS DECIMAL(18,2)) AS `tax_amount`,
    CASE lower(trim(`three_way_match_status`))
      WHEN 'matched' THEN 'matched'
      WHEN 'variance_within_tolerance' THEN 'variance_within_tolerance'
      WHEN 'variance_exceeds_tolerance' THEN 'variance_exceeds_tolerance'
      WHEN 'not_matched' THEN 'not_matched'
      WHEN 'bypassed' THEN 'bypassed'
      ELSE NULLIF(trim(`three_way_match_status`), '')
    END AS `three_way_match_status`,
    CASE lower(trim(`tolerance_check_result`))
      WHEN 'passed' THEN 'passed'
      WHEN 'failed' THEN 'failed'
      WHEN 'not_applicable' THEN 'not_applicable'
      ELSE NULLIF(trim(`tolerance_check_result`), '')
    END AS `tolerance_check_result`,
    TRY_CAST(NULLIF(trim(`withholding_tax_amount`), '') AS DECIMAL(18,2)) AS `withholding_tax_amount`,
    NULLIF(trim(`withholding_tax_code`), '') AS `withholding_tax_code`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_supplier_invoice
)
SELECT *
FROM typed
QUALIFY `supplier_invoice_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `supplier_invoice_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- procurement.invoice_line ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.procurement_invoice_line (
  CONSTRAINT `invoice_line_id_not_null` EXPECT (`invoice_line_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: procurement.invoice_line typed and cleaned, one row per invoice_line_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`invoice_line_id`), '') AS BIGINT) AS `invoice_line_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`goods_receipt_id`), '') AS BIGINT) AS `goods_receipt_id`,
    TRY_CAST(NULLIF(trim(`material_id`), '') AS BIGINT) AS `material_id`,
    TRY_CAST(NULLIF(trim(`po_line_id`), '') AS BIGINT) AS `po_line_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`purchase_order_id`), '') AS BIGINT) AS `purchase_order_id`,
    TRY_CAST(NULLIF(trim(`supplier_invoice_id`), '') AS BIGINT) AS `supplier_invoice_id`,
    TRY_CAST(NULLIF(trim(`amount_variance`), '') AS DECIMAL(18,2)) AS `amount_variance`,
    NULLIF(trim(`batch_number`), '') AS `batch_number`,
    NULLIF(trim(`blocking_reason`), '') AS `blocking_reason`,
    NULLIF(trim(`country_of_origin`), '') AS `country_of_origin`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`delivery_note_number`), '') AS `delivery_note_number`,
    TRY_CAST(NULLIF(trim(`discount_amount`), '') AS DECIMAL(18,2)) AS `discount_amount`,
    TRY_CAST(NULLIF(trim(`discount_percentage`), '') AS DECIMAL(5,2)) AS `discount_percentage`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    TRY_CAST(NULLIF(trim(`invoiced_quantity`), '') AS DECIMAL(18,3)) AS `invoiced_quantity`,
    TRY_CAST(NULLIF(trim(`line_gross_amount`), '') AS DECIMAL(18,2)) AS `line_gross_amount`,
    TRY_CAST(NULLIF(trim(`line_net_amount`), '') AS DECIMAL(18,2)) AS `line_net_amount`,
    TRY_CAST(NULLIF(trim(`line_number`), '') AS INT) AS `line_number`,
    TRY_CAST(NULLIF(trim(`line_tax_amount`), '') AS DECIMAL(18,2)) AS `line_tax_amount`,
    NULLIF(trim(`line_text`), '') AS `line_text`,
    CASE lower(trim(`match_status`))
      WHEN 'matched' THEN 'matched'
      WHEN 'quantity_variance' THEN 'quantity_variance'
      WHEN 'price_variance' THEN 'price_variance'
      WHEN 'unmatched' THEN 'unmatched'
      WHEN 'blocked' THEN 'blocked'
      WHEN 'approved' THEN 'approved'
      ELSE NULLIF(trim(`match_status`), '')
    END AS `match_status`,
    NULLIF(trim(`material_description`), '') AS `material_description`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`payment_terms_code`), '') AS `payment_terms_code`,
    NULLIF(trim(`plant_code`), '') AS `plant_code`,
    TRY_CAST(NULLIF(trim(`price_variance`), '') AS DECIMAL(18,2)) AS `price_variance`,
    TRY_CAST(NULLIF(trim(`quantity_variance`), '') AS DECIMAL(18,3)) AS `quantity_variance`,
    NULLIF(trim(`sds_document_number`), '') AS `sds_document_number`,
    NULLIF(trim(`storage_location_code`), '') AS `storage_location_code`,
    CASE lower(trim(`sustainability_certification`))
      WHEN 'fsc' THEN 'FSC'
      WHEN 'rspo' THEN 'RSPO'
      WHEN 'fairtrade' THEN 'FAIRTRADE'
      WHEN 'organic' THEN 'ORGANIC'
      WHEN 'rainforest_alliance' THEN 'RAINFOREST_ALLIANCE'
      WHEN 'none' THEN 'NONE'
      ELSE NULLIF(trim(`sustainability_certification`), '')
    END AS `sustainability_certification`,
    NULLIF(trim(`tax_code`), '') AS `tax_code`,
    TRY_CAST(NULLIF(trim(`tax_rate_percentage`), '') AS DECIMAL(5,2)) AS `tax_rate_percentage`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`unit_price`), '') AS DECIMAL(18,4)) AS `unit_price`,
    TRY_CAST(NULLIF(trim(`withholding_tax_amount`), '') AS DECIMAL(18,2)) AS `withholding_tax_amount`,
    NULLIF(trim(`withholding_tax_code`), '') AS `withholding_tax_code`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_invoice_line
)
SELECT *
FROM typed
QUALIFY `invoice_line_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `invoice_line_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- procurement.spend_category ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.procurement_spend_category (
  CONSTRAINT `spend_category_id_not_null` EXPECT (`spend_category_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: procurement.spend_category typed and cleaned, one row per spend_category_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`spend_category_id`), '') AS BIGINT) AS `spend_category_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`parent_category_spend_category_id`), '') AS BIGINT) AS `parent_category_spend_category_id`,
    TRY_CAST(NULLIF(trim(`annual_spend_budget_amount`), '') AS DECIMAL(18,2)) AS `annual_spend_budget_amount`,
    NULLIF(trim(`category_code`), '') AS `category_code`,
    NULLIF(trim(`category_description`), '') AS `category_description`,
    CASE lower(trim(`category_level`))
      WHEN 'l1' THEN 'L1'
      WHEN 'l2' THEN 'L2'
      WHEN 'l3' THEN 'L3'
      WHEN 'l4' THEN 'L4'
      ELSE NULLIF(trim(`category_level`), '')
    END AS `category_level`,
    NULLIF(trim(`category_name`), '') AS `category_name`,
    CASE lower(trim(`category_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'under_review' THEN 'under_review'
      WHEN 'consolidating' THEN 'consolidating'
      WHEN 'phasing_out' THEN 'phasing_out'
      ELSE NULLIF(trim(`category_status`), '')
    END AS `category_status`,
    NULLIF(trim(`commodity_type`), '') AS `commodity_type`,
    TRY_CAST(NULLIF(trim(`contract_coverage_percentage`), '') AS DECIMAL(5,2)) AS `contract_coverage_percentage`,
    TRY_CAST(NULLIF(trim(`cost_savings_target_percentage`), '') AS DECIMAL(5,2)) AS `cost_savings_target_percentage`,
    NULLIF(trim(`created_by_user`), '') AS `created_by_user`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    NULLIF(trim(`last_modified_by_user`), '') AS `last_modified_by_user`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_date(trim(`last_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_review_date`) AS DATE)) AS `last_review_date`,
    TRY_CAST(NULLIF(trim(`lead_time_days_typical`), '') AS INT) AS `lead_time_days_typical`,
    NULLIF(trim(`material_group`), '') AS `material_group`,
    CASE WHEN lower(trim(`moq_applicable_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`moq_applicable_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `moq_applicable_flag`,
    COALESCE(try_to_date(trim(`next_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`next_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`next_review_date`) AS DATE)) AS `next_review_date`,
    NULLIF(trim(`preferred_sourcing_strategy`), '') AS `preferred_sourcing_strategy`,
    NULLIF(trim(`procurement_organization`), '') AS `procurement_organization`,
    NULLIF(trim(`purchasing_group`), '') AS `purchasing_group`,
    NULLIF(trim(`regulatory_framework`), '') AS `regulatory_framework`,
    CASE lower(trim(`risk_profile`))
      WHEN 'high_risk' THEN 'high_risk'
      WHEN 'medium_risk' THEN 'medium_risk'
      WHEN 'low_risk' THEN 'low_risk'
      ELSE NULLIF(trim(`risk_profile`), '')
    END AS `risk_profile`,
    CASE WHEN lower(trim(`sds_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`sds_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sds_required_flag`,
    CASE lower(trim(`spend_visibility_level`))
      WHEN 'high' THEN 'high'
      WHEN 'medium' THEN 'medium'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`spend_visibility_level`), '')
    END AS `spend_visibility_level`,
    CASE lower(trim(`strategic_importance`))
      WHEN 'critical' THEN 'critical'
      WHEN 'strategic' THEN 'strategic'
      WHEN 'tactical' THEN 'tactical'
      WHEN 'non_critical' THEN 'non_critical'
      ELSE NULLIF(trim(`strategic_importance`), '')
    END AS `strategic_importance`,
    TRY_CAST(NULLIF(trim(`supplier_consolidation_target`), '') AS INT) AS `supplier_consolidation_target`,
    CASE WHEN lower(trim(`sustainable_sourcing_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`sustainable_sourcing_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sustainable_sourcing_flag`,
    NULLIF(trim(`unspsc_code`), '') AS `unspsc_code`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_spend_category
)
SELECT *
FROM typed
QUALIFY `spend_category_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `spend_category_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- procurement.approved_supplier_list ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.procurement_approved_supplier_list (
  CONSTRAINT `approved_supplier_list_id_not_null` EXPECT (`approved_supplier_list_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: procurement.approved_supplier_list typed and cleaned, one row per approved_supplier_list_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`approved_supplier_list_id`), '') AS BIGINT) AS `approved_supplier_list_id`,
    TRY_CAST(NULLIF(trim(`inspection_plan_id`), '') AS BIGINT) AS `inspection_plan_id`,
    TRY_CAST(NULLIF(trim(`material_id`), '') AS BIGINT) AS `material_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`specification_id`), '') AS BIGINT) AS `specification_id`,
    TRY_CAST(NULLIF(trim(`spend_category_id`), '') AS BIGINT) AS `spend_category_id`,
    TRY_CAST(NULLIF(trim(`supplier_contract_id`), '') AS BIGINT) AS `supplier_contract_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`supplier_site_id`), '') AS BIGINT) AS `supplier_site_id`,
    NULLIF(trim(`approval_authority`), '') AS `approval_authority`,
    CASE lower(trim(`approval_basis`))
      WHEN 'audit' THEN 'audit'
      WHEN 'certification' THEN 'certification'
      WHEN 'qualification_test' THEN 'qualification_test'
      WHEN 'performance_review' THEN 'performance_review'
      WHEN 'risk_assessment' THEN 'risk_assessment'
      WHEN 'legacy_approval' THEN 'legacy_approval'
      ELSE NULLIF(trim(`approval_basis`), '')
    END AS `approval_basis`,
    COALESCE(try_to_date(trim(`approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_date`) AS DATE)) AS `approval_date`,
    COALESCE(try_to_date(trim(`approval_expiration_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_expiration_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_expiration_date`) AS DATE)) AS `approval_expiration_date`,
    CASE lower(trim(`approval_status`))
      WHEN 'approved' THEN 'approved'
      WHEN 'conditional' THEN 'conditional'
      WHEN 'blocked' THEN 'blocked'
      WHEN 'delisted' THEN 'delisted'
      WHEN 'pending' THEN 'pending'
      WHEN 'suspended' THEN 'suspended'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    COALESCE(try_to_date(trim(`blocking_date`), 'yyyy-MM-dd'), try_to_date(trim(`blocking_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`blocking_date`) AS DATE)) AS `blocking_date`,
    NULLIF(trim(`blocking_reason`), '') AS `blocking_reason`,
    CASE lower(trim(`compliance_status`))
      WHEN 'compliant' THEN 'compliant'
      WHEN 'non_compliant' THEN 'non_compliant'
      WHEN 'under_review' THEN 'under_review'
      WHEN 'exempted' THEN 'exempted'
      ELSE NULLIF(trim(`compliance_status`), '')
    END AS `compliance_status`,
    NULLIF(trim(`conditional_terms`), '') AS `conditional_terms`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE lower(trim(`delivery_rating`))
      WHEN 'a' THEN 'A'
      WHEN 'b' THEN 'B'
      WHEN 'c' THEN 'C'
      WHEN 'd' THEN 'D'
      WHEN 'f' THEN 'F'
      ELSE NULLIF(trim(`delivery_rating`), '')
    END AS `delivery_rating`,
    CASE WHEN lower(trim(`edi_enabled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`edi_enabled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `edi_enabled_flag`,
    CASE WHEN lower(trim(`inspection_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`inspection_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `inspection_required_flag`,
    COALESCE(try_to_date(trim(`last_audit_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_audit_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_audit_date`) AS DATE)) AS `last_audit_date`,
    NULLIF(trim(`last_modified_by`), '') AS `last_modified_by`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`lead_time_days`), '') AS INT) AS `lead_time_days`,
    TRY_CAST(NULLIF(trim(`moq_quantity`), '') AS DECIMAL(18,3)) AS `moq_quantity`,
    NULLIF(trim(`moq_unit`), '') AS `moq_unit`,
    COALESCE(try_to_date(trim(`next_audit_date`), 'yyyy-MM-dd'), try_to_date(trim(`next_audit_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`next_audit_date`) AS DATE)) AS `next_audit_date`,
    NULLIF(trim(`notes`), '') AS `notes`,
    NULLIF(trim(`plant_code`), '') AS `plant_code`,
    CASE WHEN lower(trim(`preferred_supplier_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`preferred_supplier_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `preferred_supplier_flag`,
    COALESCE(try_to_date(trim(`price_validity_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`price_validity_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`price_validity_end_date`) AS DATE)) AS `price_validity_end_date`,
    COALESCE(try_to_date(trim(`price_validity_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`price_validity_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`price_validity_start_date`) AS DATE)) AS `price_validity_start_date`,
    CASE lower(trim(`quality_rating`))
      WHEN 'a' THEN 'A'
      WHEN 'b' THEN 'B'
      WHEN 'c' THEN 'C'
      WHEN 'd' THEN 'D'
      WHEN 'f' THEN 'F'
      ELSE NULLIF(trim(`quality_rating`), '')
    END AS `quality_rating`,
    COALESCE(try_to_date(trim(`re_evaluation_due_date`), 'yyyy-MM-dd'), try_to_date(trim(`re_evaluation_due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`re_evaluation_due_date`) AS DATE)) AS `re_evaluation_due_date`,
    CASE lower(trim(`risk_category`))
      WHEN 'low' THEN 'low'
      WHEN 'medium' THEN 'medium'
      WHEN 'high' THEN 'high'
      WHEN 'critical' THEN 'critical'
      ELSE NULLIF(trim(`risk_category`), '')
    END AS `risk_category`,
    CASE WHEN lower(trim(`sole_source_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`sole_source_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sole_source_flag`,
    NULLIF(trim(`sustainability_certification`), '') AS `sustainability_certification`,
    CASE WHEN lower(trim(`vmi_eligible_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`vmi_eligible_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `vmi_eligible_flag`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.procurement_approved_supplier_list
)
SELECT *
FROM typed
QUALIFY `approved_supplier_list_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `approved_supplier_list_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;
